apply:
catch {
    $why = $_.Exception.Message
    if ($why -match '0x80073D02') { throw (Get-DsoText 'Rejestracja pakietu {0} nie powiodła się, bo Microsoft Store jest teraz w użyciu (0x80073D02; zaraz po zalogowaniu Windows sam go używa przez chwilę): zamknij Sklep, odczekaj minutę i uruchom naprawę ponownie. Szczegóły: {1}' $target.PackageFullName $why) }
    throw (Get-DsoText 'Rejestracja pakietu {0} nie powiodła się: {1}' $target.PackageFullName $why)
}
